# fulfillment/domain/stock_level.py — the Fulfillment context's own model
from dataclasses import dataclass

@dataclass(frozen=True)
class StockLevel:
    units: int


# fulfillment/acl/legacy_inventory_translator.py — the anti-corruption layer
# Only this file knows the legacy system's quirks.
class LegacyInventoryTranslator:
    def __init__(self, legacy_client):
        self.legacy_client = legacy_client

    def get_stock_level(self, sku: str) -> StockLevel:
        raw = self.legacy_client.fetch_qty(sku)   # returns qty_on_hand_1000s, an int in thousands
        return StockLevel(units=raw * 1000)
```

Every other file in the Fulfillment context works with `StockLevel(units=...)` and has no idea the legacy system's unit is thousands, or that it's even a separate system at all.
